def B(trad, sysline, body, extra=""):
    return f"tradition={trad}\nsystems_used={sysline}\n{body}\n{extra}".strip()

def rev(timing_init, timing_rev, disp, gran):
    return (f"R61-REV1-2二路复推：初推={timing_init}；复推={timing_rev}；处置={disp}。"
            f"R61-REV1-3尺度核：两路同尺度。R61-REV1-4粒度核：{gran}")

LYT = lambda cm=False, ru=False, di=False, rs="": {"changed_main":cm,"reserve_used":ru,"disputed":di,"reason":rs}
