P["BZ-104"]=("方向：病灾之造，负向。断语：己土丑月，寒湿土弱，壬癸财星三透、子丑水势泛滥，双酉食伤泄气，全局无火调候暖局，主自幼体弱、寒湿入络，一生以疾病为最大关口；青少年行运再逢水旺流年（约十五至二十岁间水年叠加之年）有重大疾病、手术或住院之险，须过此关方论寿元；非夭折格，但病灾断语重于功名财禄。应期/时间窗：以年为单位，先定青少年段、再定水旺流年为危年，依据为财多身弱、无火救应得值年引动。置信分层：病象层中高、危年层低。", B("bazi","八字子平单法（调候先行）","四柱壬子癸丑己酉癸酉：邵氏疾病之例体裁；寒湿无火为病根，酉金食伤只泄不暖，故主断落病灾而非吉凶泛论。"+rev("运年触发路：水年引动财泛身弱","值年值月路：丑子水月同气、与初推同为年档","二路同向，保留年档区间","危年断项指针1条（水势值年），降为青少年段内水旺流年区间交付")),0.48,NT)
P["BZ-105"]=("方向：武职得位、中年官运通，终局正向；回溯核验段：过去两关键年份一主升迁调动、一主伤病口舌。断语：丙火戌月，寅午拱火、甲印透时，身旺任官，子水正官坐日与午火禄冲，子午冲主军职迁转与冲撞之伤，主部队军官得实职；回溯所验两年应为官星值年（子年）之升调与冲禄之年（午年或子年冲动）的职任变动兼轻伤病。应期/时间窗：以年为单位，中年行金水运（财官值运）为升职段，依据为身旺得官运引动。置信分层：武贵层中、回溯年份层低（卡内未给两年年份原文，不断具体公历年份）。", B("bazi","八字子平单法；输入注记：本题为回溯验证体裁（卡内case_type=retrodiction），过去年份原文未载，不断确年","四柱壬寅庚戌丙子甲午：丙火有寅午之势，官星子水坐日得壬透，武职之象成；子午冲为一生迁转主线。"+rev("运年触发路：金水运财官引动升职","合冲引动路：子午冲值年同指迁转关口","二路同向，保留","回溯年份断项指针0条确据，按R61-REV1-4删确年、只留职任变动类型交付")),0.50,NT)
P["BZ-301"]=("方向：衰败，负向。断语：中国国民党至2022年（民国111年）运势走入低谷：失去中央执政地位已成定局且无力在该年重返执政，党内分裂与路线之争公开化，面临存亡边缘的舆论与改组压力。应期/时间窗：以年为单位，定点2022年本身即问年，依据为公开预言所指年份。置信分层：方向层中、细节层低。输入残损：无建党命盘、四柱与起运数据，仅凭题面作断，大幅降置信。", B("bazi（题面自带tradition=bazi，然无命盘输入）","八字/地运类公开预言体裁（无盘推断）","输入残损注记：卡内无四柱、无起运、无排盘附件，无法按子平程序核盘；仅据2022为该党创党110周年、逢双冲之年象作方向断。"+rev("无盘可推，应期即问年2022（初推）","周年数推路同指2022（复推）","二路同点（皆题面给定），保留问年坐标","细节断项指针0条，按R61-REV1-4删具体事件细节、只留方向与存亡压力层级交付")),0.38,NT)
P["BZ-302"]=("方向：凶终，负向；命书末句应验方向：受累于吴。断语：此命前段少年中年富贵已如命书所论，末句『受累于吴』主其晚节因一位吴姓关键人物（或吴姓所主之势力/牵连）而罹大祸——因之获罪下狱、身败名裂以至丧命，祸不在吴人加害之明枪，而在与之牵连共事之累。应期/时间窗：以年为单位，祸应在晚年行运与吴姓者共事之后数年内，依据为命书末句所指之人际触发（无四柱可核运年，不断具体年份）。置信分层：末句应验层中、机制层低。输入残损：无四柱、无命书全文，仅末句可断。", B("bazi（批命书体裁，无四柱输入）","八字批命书末句单断","输入残损注记：卡内无四柱与命书全文，仅存末句四字与前段富贵之转述；按批命书体例，末句为全书收束之断，权重最高。"+rev("初推：末句触发路指向晚年共事后数年","复推：无运年可核，明写复推无第二机制、粒度降档","二路不合（第二路无据），按R61-REV1-2降档为晚年区间交付","获罪形态断项指针1条（末句文字锚），降为倾向表述（获罪下狱以至丧命）交付")),0.45,NT)
P["BZ-303"]=("方向：先高后衰、2024年为转折，终局负向。断语：香港地运八运（2004–2023）旺山旺向之气至2016年已近尾声，楼价在高位反复见顶，入九运（2024年起）地运转衰，经济与楼市同步进入明显下行周期，高位不复。应期/时间窗：以年为单位，先定运界2024年为转折年、再及转折前后数年下行段，依据为三元九运换运之年。置信分层：换运方向层中高、幅度层中。输入残损：无具体峦头理气盘面，仅以地运元运作断。", B("fengshui（卡内tradition=fengshui）","风水地运（三元九运）单法","输入残损注记：卡内无楼盘/峦头数据，只有公开访问之问；按元运交替作宏观断。"+rev("初推：元运路定2024换运转衰","复推：楼价高位年份路同指2020年代前半见顶回落","二路同向，保留2024年坐标","幅度断项指针1条（元运），降为倾向表述交付")),0.55,NT)
P["BZ-304"]=("方向：疫情反复、年内不息，终局先凶后缓。断语：庚子年新冠疫情上半年为高峰扩散段，新加坡须行阻断管制方能压低；年中一度缓和而非清零，年尾有再起之波，须待辛丑年（2021年）年中以后随疫苗与管控方渐次平息，庚子年内不断言疫终。应期/时间窗：以月为单位，先定2020年内高峰段、再定2021年年中为平息窗，依据为庚子金水寒湿之气至辛丑土金渐收。置信分层：进程层中、月份层低。输入残损：无排盘附件，仅凭流年干支与发问时点作断。", B("fengshui/流年（卡内tradition=fengshui）","流年干支气运推断（无盘）","输入残损注记：卡内无课盘命盘，仅问庚子年走势；按干支气运与当时已发事实（3月病例上升）作进程断。"+rev("初推：干支气运路定年尾再波、次年年中平息","复推：管制事件路同指年中缓和非清零","二路同向，保留月档区间","月份断项指针1条，降为相邻数月区间交付")),0.45,NT)
# ---------- B05 DT liuyao ----------
P["DT-001"]=("方向：父病凶，负向（单一终局）。断语：占父以父母为用神，父母子水伏于初爻寅木之下，伏神休囚、飞神泄之，五爻官鬼申金独发为病势发动，鬼动虽生伏神而实主病进；解卦虽有疏解之名，用神伏藏无力，终局断父病沉重难愈，近段（旬内）病势转剧。应期：跨度定为日档（近病以日为尺度，父病危急、卦有独发之爻支持日级定位）；窗口为占后一旬内，主坐标取申日——官鬼申金值日、病势最剧之日，依据为动爻逢值；备选子日（用神逢值）只入复推不并陈。", B("liuyao","六爻纳甲单法","雷水解，五爻官鬼庚申金独发；父母子水伏初爻寅木下。用神伏藏+鬼独发，对象复述：承受对象=占者之父，应验对象=父母爻所指之父，同一。动化定性核对：动化方向—申金动无化进退、回头生克无；反转条件—无三类反转信号全立，不翻转。病占原神子孙午火不旺，无力制鬼。"+rev("初推逢值路：申日（鬼爻值日）","复推冲实/填实路：子水伏神逢子日填实同在一旬窗内、点位后移","两路异点同窗，按(h)与终局凶向自洽取鬼值日申日为主坐标，子日舍弃理由：填实主用神露头而非病剧、与终局方向层级不合","病剧形态断项指针2条（鬼独发+用神伏藏），保留")),0.52,LYT(False,False,False,"六爻常规断：用神伏藏、鬼爻独发，初判即定凶向，无改主断、无备用改判、原文无歧义。"))
P["DT-002"]=("方向：母子平安，顺产，正向（单一终局）。断语：占妻孕，妻以妻财为用、胎以子孙为用；子孙戌土持世旺相，妻财酉金伏世下得飞神生扶且得长生，主妻安、胎安，临产顺遂，母子俱保。应期：跨度定为日档（产期以日计、卦中世应俱动支持日级）；窗口为近期一旬内，主坐标取戌日——子孙用神值日，依据为逢值；备选酉日（财爻值日）只入复推。原文动爻叙述涉飞伏换算有歧（卡内自述），本断以卡内整理之装卦为准并标注。", B("liuyao","六爻纳甲单法","山水蒙，三爻兄弟午火、六爻父母寅木动；子孙戌土持世、妻财酉金伏世下飞来生伏。对象复述：承受对象=占者之妻与胎，应验对象=妻财爻之妻、子孙爻之胎，同一。动化定性核对：动化方向—午火动泄、寅木动生火，无化进退定性翻转；反转条件—不全立，不翻转。"+rev("初推逢值路：戌日子孙值日","复推填实路：酉金伏神逢酉日填实同窗后点","两路异点，按(h)取胎神值日戌日（与顺产终局自洽），酉日舍弃理由：财伏填实主母体露头、非产时主点","顺产断项指针2条（子孙持世旺+财伏得生），保留")),0.55,LYT(False,False,True,"原文动爻以本宫飞伏语叙述、与图解本整理（蒙之升）读法有歧，卡内已并记；本断按卡内装卦表作断，故disputed=true留痕。"))
P["DT-003"]=("方向：人安而归迟，正向保人、负向于速归（单一终局取人安迟归）。断语：占子出商未归，以子孙为用，子孙申金临应得戌土生扶，人身无大害；然二爻父母午火旺相独发克申金，艮卦主止、行人被阻，主途中受阻滞留、归期迟延，且有一场途中惊险或病耗。应期：跨度定为日档（行人归期以日计）；窗口为占后一旬至半月，主坐标取申日——用神值日、人归见信，依据为逢值；备选午日（动爻值日、阻滞最显）只入复推。", B("liuyao","六爻纳甲单法","艮为山八纯，二爻父母丙午火独发。对象复述：承受对象=出商之子，应验对象=子孙申金所指之子，同一。动化定性核对：动化方向—午火动克用神、无化；反转条件—父母动主消息至，不构成人亡之反转全链，不翻转人安之判。"+rev("初推逢值路：申日用神值日","复推冲实路：午火动爻逢午日冲实同在窗前段","两路异点，按(h)取申日（与人安归家终局自洽），午日舍弃理由：午日主阻滞发动、非归点","惊险断项指针1条（午火克金），按R61-REV1-4降为倾向表述交付")),0.50,LYT(False,False,False,"用神得生、动爻克用，初判人安迟归即定，无改判无歧义。"))
P["DT-004"]=("方向：子病凶，负向（单一终局）。断语：占子病以子孙为用，子孙丑土居二爻发动而休囚，官鬼亥水持世旺相临身，鬼旺用弱、药神（子孙）虽动而力薄难制旺鬼，主病势沉重、难愈有危。应期：跨度定为日档（近病危重以日为尺度）；窗口为占后一旬内，主坐标取亥日——官鬼值日、病势最剧，依据为逢值；备选丑日（用神值日）只入复推。原文动爻飞伏叙述有歧（卡内自述三处并记），以卡内装卦表为准。", B("liuyao","六爻纳甲单法","天火同人，子孙丑土、官鬼亥水发动（原文飞伏交错、卡内并记）。对象复述：承受对象=患病之子，应验对象=子孙丑土所指之子，同一。动化定性核对：动化方向—丑土动无进退、亥水世旺；反转条件—子孙动本为制鬼之路，然用弱鬼旺不达翻转门槛，只降格不翻转。"+rev("初推逢值路：亥日鬼值日","复推填实路：丑日用神值日同窗","两路异点，按(h)取亥日（与凶终局自洽），丑日舍弃理由：用神值日力仍不足制鬼","危象断项指针2条（鬼持世旺+用弱），保留")),0.55,LYT(False,False,True,"原文以飞伏交错语叙述动爻、图解本整理与原文读法有歧，卡内三处并记；按装卦表作断，disputed=true留痕。"))
P["DT-005"]=("方向：子病可愈，正向（单一终局）。断语：占子病以子孙为用，子孙亥水临应、冬令旺相，官鬼午火休囚无力，子孙旺而能制鬼；五爻兄弟酉金独发生亥水、助用神之势，困卦先困后通，主病虽缠绵而终可痊愈，近段（旬内）见转机。应期：跨度定为日档（近病以日为尺度）；窗口为占后一旬内，主坐标取亥日——用神值日、愈象最显，依据为逢值；备选酉日（原神值日）只入复推。", B("liuyao","六爻纳甲单法","泽水困，五爻兄弟丁酉金独发。对象复述：承受对象=患病之子，应验对象=子孙亥水所指之子，同一。动化定性核对：动化方向—酉金动生用神、无化退；反转条件—无凶向反转信号全立，不翻转。"+rev("初推逢值路：亥日用神值日","复推冲实路：酉金原神逢酉日同窗前点","两路异点，按(h)取亥日（与愈之终局自洽），酉日舍弃理由：原神值日主药力至、非愈点本身","转机断项指针2条（子孙旺相+原神动生），保留")),0.60,LYT(False,False,False,"子孙旺鬼衰，初判可愈即定，无改判无歧义。"))
P["DT-006"]=("方向：子病大凶，负向（单一终局）。断语：父占子病以子孙为用，子孙巳火伏于五爻父母子水之下，飞神子水克伏神巳火，用神伏藏且受飞克、无气无救；四爻财动、五爻父动皆不生子孙，主病入膏肓、难愈有夭危之险。应期：跨度定为日档（近病危重以日为尺度）；窗口为占后一旬内，主坐标取巳日——伏神逢值出头而正受子水克制、危象最显，依据为逢值兼冲飞（巳亥冲、此卦飞在亥位关系）之复核；备选子日（飞神值日）只入复推。原文动爻为飞伏语（卡内自述），以装卦表为准。", B("liuyao","六爻纳甲单法","山风蛊，子孙巳火伏五爻父母子水下。对象复述：承受对象=患病之子（父为之占），应验对象=伏神子孙巳火所指之子，同一。动化定性核对：动化方向—财父发动不生用神；反转条件—伏神得冲开本为出头之路，然飞神克伏不解，不达翻转门槛。"+rev("初推逢值路：巳日伏神值日","复推冲实路：子日飞神值日同窗、克势更显","两路异点，按(h)取巳日（伏神露头受克、与凶终局自洽），子日舍弃理由：子日主飞克加剧的过程点、非危候主点","夭危断项指针2条（伏神受飞克+无原神救应），保留")),0.60,LYT(False,False,True,"原文动爻以飞伏语叙述、图解本整理为蛊之鼎，读法有歧；按卡内装卦与伏神关系作断，disputed=true留痕。"))
P["DT-007"]=("方向：家宅不宁、主破财失物，负向（单一终局，轻级）。断语：占家宅以世爻与父母为宅象，世临兄弟午火，四爻妻财酉金临玄武发动，玄武主暗昧盗失，财动入宅爻之间，主家中有暗耗破财、失物或被盗之扰，兼口舌不宁；人丁无大凶，等级只到财物与宅安层级，不断人亡重灾。应期：跨度定为日档（宅中失扰以日计）；窗口为占后一旬内，主坐标取酉日——动爻财星值日、事发见形，依据为逢值；备选戌日（日辰、父母戌位相关）只入复推。", B("liuyao","六爻纳甲单法","火水未济，四爻玄武妻财己酉金发动。对象核对：承受对象=所占之家宅及其财物，应验对象=妻财酉金所指之财物，同一（非人对象不回收到人身上）。动化定性核对：动化方向—酉金动无化进退；反转条件—无涉人安危之信号，不升格。"+rev("初推逢值路：酉日财动值日","复推冲实路：卯日冲酉同在旬外缘","两路异点，按(h)取酉日，卯日舍弃理由：冲动主事后发觉、非事发主点且出主窗","失物断项指针2条（玄武乘财+财爻独发），保留；处所无指针不断具体处所")),0.50,LYT(False,False,False,"财动玄武，初判宅扰破财即定，无改判无歧义。"))
P["LR-001"]=("方向：有惊无险、人可生还，正向（单一终局）。断语：西安事变中蒋介石性命无虞，扣押为政治要价而非行刺之局，主先惊后解、经斡旋获释回京。应期：跨度定为日档（事变扣押以日计）；窗口为事变后两周内，主坐标取事变后约十三日（12月25日前后）获释，依据为题面时点（12月12日事变）顺推之谈判周期。置信分层：生还方向层中、日期层低。输入残损严重：卡内无课式、无三传、无起课干支，无法按六壬程序核盘，大幅降置信。", B("liuren（题面无tradition字段，据占问体裁与韦千里六壬/占卜背景自决为大六壬门类；卡内无盘面）","大六壬（无盘，仅据事理与占问体裁）","输入残损注记：卡内无课式、四课、三传、空亡任何盘面数据，守方法第八节不臆补盘面；仅据扣押性质（兵谏要价而非弑杀）与占问为生死安危作方向断。已载面：生死面已断；行程面（获释）已断；余面题面未载。"+rev("初推：题面时点顺推谈判周期得两周内获释","复推：无盘面机制可换，明写复推无第二机制、粒度降档","二路不合（第二路无据），按R61-REV1-2降档为两周窗口交付、主坐标只作窗内倾向点","获释日期断项指针0条盘面据，按R61-REV1-4降为窗口区间交付")),0.42,NT)
# LR2 liuren
def LR(trad_note, body, revtxt):
    return B("liuren","大六壬单法（指南门类占断）", trad_note+" "+body+" "+revtxt)
P["LR2-013"]=("方向：回奏得解、无大罪，正向（单一终局）。断语：沈云生被参劾回奏，铸印课主印信诏命，三传巳（天空）→戌（螣蛇）→卯（太常），初传虚惊、中传缠扰，末传卯木太常为天恩常客之将，主奏对得旨、参劾不致重谴，惊扰后平、官位可保。应期：跨度定为日档（章奏回奏以日计）；窗口为占后一旬内，主坐标取卯日——末传值日、结案见分晓，依据为六壬逢值路；备选戌日（中传值日）只入复推。", LR("癸酉年二月丁丑日丙午时，重审铸印课；日干丁为占者本人，类神取官鬼与朱雀文书并参。","三传链：巳火为丁之禄后虚位乘天空主虚参，戌乘螣蛇主中途惊挠，卯太常收束主恩诏平复。空亡申酉、丑寅落空，末传卯不落空，断语可落点。",rev("初推逢值路：卯日末传值日","复推逢冲合路：卯戌合、中传戌日同窗前点","两路异点，按取末传结案点卯日，戌日舍弃理由：戌主缠扰过程点","官位可保断项指针2条（太常末传+铸印课格），保留")),0.52,NT)
P["LR2-014"]=("方向：在狱者得救、不死，正向（单一终局）。断语：偶占一课所主之人虽在狱中，三传申（六合）→亥（贵人）→寅（玄武），贵人居中传临门，主有贵人援救、狱事得解，不至死罪；末传寅木玄武，主其案涉阴私盗失之牵连，出狱后仍有余波。应期：跨度定为月档（狱事解救以月计，先定月不径落日）；窗口为占后两月内，主坐标取亥月/亥日层级之亥——贵人值位，依据为逢值路（月档内以亥为坐标不断单日）；备选申（初传）只入复推。", LR("辛未年四月丙辰日甲午时，重审玄胎课；占时不知何人，按课所主之人断，类神以日支辰为其宅、日干丙为占者。","贵人乘亥入传为全课救应；申金六合主和解，寅玄武主案情阴私。空亡子丑、卯辰落空，日支辰落空主其眼下处境虚陷，与在狱合。",rev("初推逢值路：亥位贵人值位","复推出空路：辰支落空逢辰值填实同指近两月","两路同档异点，按贵人救应优先取亥位，辰点舍弃理由：填实主处境露头非解救点","贵人援救断项指针2条（贵人入传+六合初传），保留")),0.50,NT)
P["LR2-015"]=("方向：重辟难逃、凶，负向（单一终局）。断语：冯允升刑部已定重罪，三传午（天空）→丑（天后）→申（勾陈），午为乙木日干之死气所行、乘天空主虚望，末传申金勾陈为刑狱勾连之极，主出狱无望、重辟定案难改，纵有后宫之请亦不解。应期：跨度定为月档（定案行刑以月计）；窗口为占后一月内，主坐标取申——末传勾陈值位、定案落点，依据为逢值路；备选午（初传虚望）只入复推。", LR("丙子年三月乙未日己卯时，重审课；日干乙为其人，官鬼金势入传收尾。","三传火土金递克日干所生，救应不见贵人青龙，勾陈末传锁狱。空亡辰巳、亥子落空，不碍申位落点。",rev("初推逢值路：申位末传值位","复推逢冲路：寅申冲、寅位同档为冲动定案点","两路同档，按末传收束取申位，寅点舍弃理由：冲主发动非落点","重辟断项指针2条（勾陈末传+无救应），保留")),0.55,NT)
P["LR2-016"]=("方向：不得即出、久系后方出，负向于近段（单一终局取久系）。断语：陈秋桃被逮占出狱，同难者言指日即出而课不许速出：三传亥（螣蛇）→午（天空）→丑（天后），初传螣蛇主惊缠，中传午乘天空主『即出』之说为空言，末传丑为日干己之墓库，主收系久坐；出狱须待墓库冲开之年时，迟以年计。应期：跨度定为年档（久系以年计，先定年）；窗口为占后数年内，主坐标取丑年/丑位冲墓得开之后段，依据为逢冲开墓路；备选亥（初传）只入复推。", LR("丙子年三月己酉日丁卯时，蓦越重审课；日干己寄未，丑为金墓亦土之库。","螣蛇初传主其惊恐缠绕，天空居中正破『即出』之言，末传归墓主久。空亡寅卯、酉戌落空，日支酉落空主外援虚浮。",rev("初推逢冲路：丑墓逢丑值/未冲开墓","复推逢值路：亥水初传值位主惊缠非出狱","两路异档，先按(k)定年档（久系），取丑位后段，亥点舍弃理由：尺度不合（日月级惊缠点）","久系断项指针2条（末传归墓+天空破速出），保留")),0.55,NT)
P["LR2-017"]=("方向：重罪难赦、凶，负向（单一终局）。断语：戚司宗失机定罪已八载，与冯允升同课同传（午天空→丑天后→申勾陈），课象不以年久而转：末传勾陈申金锁狱、救应不入传，主八载之系仍无赦解之期，终局以罪案定谳收束，不得以『久当得赦』宽断。应期：跨度定为年档（赦期以年计）；窗口为占后一年内，主坐标取申位之年时——勾陈值位、案情再定之点，依据为逢值路；备选午（虚望）只入复推。", LR("丙子年二月乙未日己卯时，重审课，与LR2-015同课式同三传（卡内自述四课同），断语同向同级，不因对象不同而改判。","同015链：火土金递进、勾陈收尾、无贵人青龙救应。",rev("初推逢值路：申位末传值位","复推逢冲路：寅位冲申同档","两路同档取申位收束，寅点舍弃理由：冲主再议非定谳点","难赦断项指针2条（勾陈末传+无救应），保留")),0.55,NT)
P["LR2-018"]=("方向：罪重难出、凶，负向（单一终局）。断语：吴振缨被逮定重辟，天狱课格已主囚系之极，三传未（青龙）→子（贵人）→巳（白虎），初传未为日干乙木之墓、青龙入墓主恩泽被收，中传贵人子水虽现而落空（亥子落空）救应无力，末传巳火白虎乘刑，主定罪难翻、狱中凶终之险重。应期：跨度定为月档（定谳以月计）；窗口为占后两月内，主坐标取巳位——白虎末传值位，依据为逢值路；备选子（贵人落空）只入复推并注明落空不取。", LR("丙子年二月乙酉日辛巳时，涉害天狱课；日干乙为其人。","青龙入墓+贵人落空+白虎收尾，三象同指救绝。空亡午未、亥子落空，初传未与贵人子俱陷空墓为关键。",rev("初推逢值路：巳位末传值位","复推出空路：子贵人逢子值出空同档后点","两路异点，按终局凶向取巳位，子点舍弃理由：贵人出空只主一线消息、力不足翻案","凶终断项指针2条（白虎末传+贵人落空），保留倾向级（险重）交付")),0.52,NT)
P["LR2-019"]=("方向：勤王不利、无功而返，负向（单一终局）。断语：奉命勤王，三传酉（朱雀）→丑（太阴）→巳（天空），进茹课主进而复退，末传巳乘天空主师行落空、令不行地；朱雀初传主军令文书先达而兵势不继，主此行受阻中途、无尺寸之功，将士有惊扰损耗而主将无性命之虞。应期：跨度定为月档（师行以月计）；窗口为出师后一月内，主坐标取巳位——末传值位、师退见分晓，依据为逢值路；备选酉（初传令达）只入复推。", LR("乙酉年四月辛酉日丙申时，重审进茹课；日干辛为将士之主，类神取官鬼与白虎行军并参，三传无白虎故损耗降级。","酉为辛禄乘朱雀主令出，丑太阴主暗耗，巳天空收尾主落空。空亡子丑、丑寅落空，中传丑落空主粮路/暗助空。",rev("初推逢值路：巳位末传值位","复推逢冲路：亥位冲巳同档","两路同档取巳位，亥点舍弃理由：冲主始退非收束点","无功断项指针2条（天空末传+进茹课格），保留；损耗断项指针1条降为倾向表述")),0.50,NT)
P["LR2-020"]=("方向：远行不利、宜缓不宜行，负向（单一终局）。断语：携妻子远行得八专课，八专主夫妻同体、事不分判，三传戌（六合）→巳（太常）→子（螣蛇），末传子水螣蛇主途中惊恐缠扰，巳子水火交战，主行至中途妻有病惊之扰、行程半途而返或改期；若必行，近段先阻、远段无大凶人身祸，只到惊病与破耗层级。应期：跨度定为日档（行期以日计）；窗口为拟行后一旬内，主坐标取子日——末传值日、惊扰见形，依据为逢值路；备选巳日（中传）只入复推。", LR("庚寅年五月庚申日丁丑时，八专绝嗣课（卡内注原书未另列空亡）；日干庚为夫、日支申为妻宅，八专干支同位正合携妻之问。","六合初传主夫妻同行之实，太常中传主衣食行李，螣蛇末传主终局惊缠。",rev("初推逢值路：子日末传值日","复推逢冲路：午日冲子同窗","两路异点取子日（值日主见形），午日舍弃理由：冲主变动消息非事发点","妻病惊断项指针1条（螣蛇末传），降为倾向表述交付")),0.48,NT)
P["LR2-021"]=("方向：女平安在途、到京迟，正向保人（单一终局）。断语：父占女行程，元首玄胎课，三传巳（贵人）→寅（六合）→亥（天空），贵人初传主一路有贵助、平安无虞，六合中传主行程和顺，末传亥乘天空主到达之期落空拖延，主人安而日至迟。应期：跨度定为日档（候人以日计）；窗口为占后一旬内，主坐标取寅日——中传六合值日、行人抵京最可能之日，依据为逢值路；备选亥日（末传、主迟至之限）只入复推。", LR("戊辰年十一月壬戌日乙巳时，元首玄胎课；日干壬为父、日支戌为女宅，行人类神以支与初传并参。","贵人、六合连珠为行人吉链，天空收尾只主迟不主凶。空亡子丑、酉戌落空，日支戌落空主其人尚在途未至宅。",rev("初推逢值路：寅日中传值日","复推填实路：戌支落空逢戌日填实同窗后点","两路异点，按行人抵宅取寅日先至之合点，戌日舍弃理由：填实主宅位落实为迟限、非最可能抵点","平安断项指针2条（贵人初传+六合中传），保留")),0.52,NT)
P["LR2-022"]=("方向：弟病先危后安、终可愈，正向（单一终局）。断语：兄为弟占病，铸印课，三传巳（天空）→戌（螣蛇）→卯（太常），初传巳火乘天空主病象虚浮惊人、中传螣蛇主缠扰反复，末传卯木太常主调治得方、饮食渐进，病根不入墓绝，终局向愈。应期：跨度定为日档（近病以日计）；窗口为占后一旬内，主坐标取卯日——末传值日、转安见分晓，依据为逢值路；备选戌日（中传缠扰最显）只入复推。对象复述：承受对象=弟观初，应验对象=三传所主之病者本人，同一。", LR("辛巳年九月丁亥日辛丑时，重审铸印课；日干丁为兄占者，以日支亥与年命类神参弟病（卡内未给年命，只据三传链断）。","巳戌卯链由虚惊转太常收束，太常为疾病门吉将主医药饮食。空亡午未、亥子落空，日支亥落空主病者元气虚浮，与初传天空合。",rev("初推逢值路：卯日末传值日","复推逢合路：卯戌合、中传戌日同窗前点","两路异点取卯日收束，戌日舍弃理由：戌主缠扰过程点","转安断项指针2条（太常末传+病根不入墓），保留")),0.50,NT)
P["LR2-023"]=("方向：病缠绵反复、凶多吉少于近段，终局偏负。断语：张澹宁占病，三交课主交错杂乱，三传卯（玄武）→午（天空）→酉（六合），初传卯木落空（寅卯空）克日干己土为鬼、乘玄武主病因阴私暗耗，午火天空主药石虚浮，末传酉金六合只主表面和缓；主病势反反复复、迁延难愈，近段防加重，纵缓亦留病根。应期：跨度定为月档（缠绵之病以月计）；窗口为占后一月内，主坐标取酉位——末传值位、缓急分晓之点，依据为逢值路；备选卯（鬼落空、出空反剧）只入复推。对象复述：承受对象=张澹宁本人，应验对象=三传所主病者本人，同一。", LR("己卯年六月己酉日戊辰时，蒿矢三交课；日干己为病者本人，卯木为官鬼克身。","初传落空之鬼主病来无形、去亦无形之反复；三交课格主多事交杂，席间家事并扰（卡内setting提及）。空亡寅卯、巳午落空，初传与中传俱落空为关键。",rev("初推逢值路：酉位末传值位","复推出空路：卯鬼逢卯出空同档主加重","两路同档异义，按终局偏负取酉位为分晓点，卯点舍弃理由：出空主病剧过程非分晓点","反复断项指针2条（三交课格+双传落空），保留")),0.46,NT)
P["LR2-024"]=("方向：病凶重、难愈，负向（单一终局）。断语：卢承山自占病，三传午（天空）→丑（天后）→申（勾陈），与狱占同传链而在疾病门主病势由虚火转入沉结，末传申金勾陈主病勾连成块、久而不解，救应不见子孙医药之将入传收尾，主病重难治、防入危候。应期：跨度定为月档（重病转归以月计）；窗口为占后一月内，主坐标取申位——末传值位、病势定局之点，依据为逢值路；备选午（初传虚火）只入复推。对象复述：承受对象=卢承山本人，应验对象=三传所主病者本人，同一。", LR("乙酉年正月己亥日己巳时，重审交车课；日干己为病者，午火为印而乘天空主生气虚浮。","火土金链递泄日干之气，勾陈收尾主沉结。空亡辰巳、亥子落空，日支亥落空主宅气虚陷。",rev("初推逢值路：申位末传值位","复推逢冲路：寅位冲申同档","两路同档取申位，寅点舍弃理由：冲主变动非定局点","危候断项指针2条（勾陈末传+无医药救应入传），保留倾向级（防入危候）交付")),0.52,NT)
# ---------- B06 LR3 ----------
P["LR3-002"]=("方向：出师先得势而后耗、正向为主（单一终局取得势无大败）。断语：总镇奉命出师江东，元首炎上课，三传午（贵人）→寅（勾陈）→戌（太常），初传午火贵人主奉命正大、军威先扬，中传勾陈主屯驻勾连、进兵迟滞，末传戌土太常主收军有粮、终局保全；主此行有声势之胜而无拓地大功，将星本人无恙。应期：跨度定为月档（师行以月计）；窗口为出师后两月内，主坐标取戌位——末传值位、收束见分晓，依据为逢值路；备选午（初传得势）只入复推。", LR("丙子年二月辛巳日辛卯时，元首炎上课；日干辛为代占之主帅类神，午火为官星乘贵人。","贵人初传定主向为正，炎上课主火势先盛。空亡申酉、辰巳落空，日支巳落空主所向之地虚实未明，故断声势胜于实功。",rev("初推逢值路：戌位末传值位","复推逢合路：寅午戌火局、中传寅位同档前点","两路异点取戌位收束，寅点舍弃理由：寅主屯驻过程点","无大败断项指针2条（贵人初传+太常末传），保留")),0.50,NT)
P["LR3-004"]=("方向：功名有成而迟，正向（单一终局）。断语：自占功名得八专曲直课，三传亥（螣蛇）→卯（玄武）→未（青龙），亥卯未木局曲直成势，末传未土青龙主最终得官得喜，然初传螣蛇、中传玄武主前段惊疑与阴私阻挠，功名须历波折而后成，成在木局成局之年时。应期：跨度定为年档（功名以年计，先定年）；窗口为占后数年内，主坐标取未年/未位——末传青龙值位，依据为逢值路；备选卯（中传）只入复推。", LR("辛未年四月己未日戊辰时，八专曲直课；日干己土，木为官星，三传全归木局正合功名之问。","曲直课格与三合木局双证官星成势；青龙收尾定终局。空亡子丑、辰巳落空，不碍木局。",rev("初推逢值路：未位末传值位","复推逢合路：卯位中传合局同档","两路同档取未位（收束点），卯点舍弃理由：卯主过程阻挠段","得官断项指针2条（木局成势+青龙末传），保留")),0.52,NT)
P["LR3-006"]=("方向：仕途平顺、小有升象而虚喜参半，终局中平偏正。断语：任台垣占仕途，元首玄胎课，三传巳（贵人）→寅（六合）→亥（天空），贵人六合连珠主仕途人际和顺、上司垂青，然末传亥水乘天空主所期之升擢有一场虚喜——名位小进或美差落空其半，不至贬谪。应期：跨度定为月档（仕途迁转以月计）；窗口为占后数月内，主坐标取寅位——中传六合值位、迁转消息落点，依据为逢值路；备选亥（末传虚喜）只入复推。", LR("癸酉年八月壬戌日戊申时，元首玄胎课；日干壬水，巳火为财、寅木为食神生官之路。","与LR2-021同课式同三传而门类不同：彼为行人取平安迟到，此为仕途取升象虚喜，断语随门类分途。空亡子丑、酉戌落空，日支戌落空主现职根基虚浮。",rev("初推逢值路：寅位中传值位","复推填实路：戌支落空逢戌值同档","两路同档取寅位，戌点舍弃理由：填实主现职落实非迁转点","虚喜断项指针2条（天空末传+贵人六合前链），保留")),0.50,NT)
P["LR3-008"]=("方向：功名可得、先空后实，正向（单一终局）。断语：自占功名得八专铸印绝嗣课，铸印课正主印绶官位，三传巳（白虎）→戌（朱雀）→卯（太阴），初传巳火落空（巳午落空）主首番声名落空或试场失利，中传朱雀主文书再达，末传卯木太阴主阴助而成，主功名迟得、得于再试或荐举之途。应期：跨度定为年档（功名以年计）；窗口为占后数年内，主坐标取卯年/卯位——末传值位，依据为逢值路；备选巳（落空之初传）只入复推并注明落空不取首点。", LR("辛巳年十月己未日癸酉时，八专铸印课；日干己土，木为官星，末传卯木官星乘太阴。","铸印课格与官星收尾双证；初传落空定先空后实之节奏。空亡子丑、巳午落空为关键。",rev("初推逢值路：卯位末传值位","复推出空路：巳逢巳值出空同档主首番落空之应","两路同档取卯位成点，巳点舍弃理由：出空主落空应验非成点","迟得断项指针2条（铸印课格+官星末传），保留")),0.50,NT)
P["LR3-010"]=("方向：仕途停滞、有口舌参劾之忧，负向（单一终局，轻级）。断语：代占在朝官员，伏吟课主停滞自守、玄胎并见，三传巳（朱雀）→申（天后）→寅（青龙），伏吟不动主其人现职久滞不迁，朱雀初传主口舌文书之扰、有一番参劾或谏诤牵连，末传青龙寅木主终不至罢黜、贵气尚存。应期：跨度定为月档（参劾迁滞以月计）；窗口为占后数月内，主坐标取申位——中传值位、事端见形，依据为逢值路；备选巳（初传口舌）只入复推。", LR("辛未年四月戊午日辛酉时，玄胎伏吟课；干支伏吟（午午、巳巳）为全课主象。","伏吟定停滞主向，朱雀定口舌门类，青龙收尾定不黜底线。空亡子丑、子丑落空，三传无一落空，断语可落点。",rev("初推逢值路：申位中传值位","复推逢冲路：寅申冲、末传寅位同档","两路同档取申位见形点，寅点舍弃理由：寅主收束保全非事端点","参劾断项指针2条（朱雀初传+伏吟课格），保留")),0.50,NT)
P["LR3-101"]=("方向：会试不中，负向（单一终局）。断语：代占会试得蒿矢课，蒿矢主虚射、力弱不中的，三传酉（天后）→戌（太阴）→亥（玄武）连茹递退，水势泄日干乙木之气，文星（父母）不入传、官星酉金乘天后阴柔无力，主此试名落孙山；纵文章可观，亦主考场缘薄、榜上无名。应期：跨度定为日档（放榜以日计、问会试结果有时点）；窗口为放榜之时，主坐标取亥日——末传值日、榜讯落定，依据为逢值路；备选酉日（初传）只入复推。", LR("丁丑年二月乙未日丙戌时，蒿矢连茹课；日干乙木，取父母文书、官鬼功名双类神，均不旺入传。","蒿矢课格为会试门凶象，连茹后退主名次无望。空亡辰巳、巳午落空，不碍亥位落点。",rev("初推逢值路：亥日末传值日","复推逢冲路：巳日冲亥同窗","两路异点取亥日（值日落定），巳日舍弃理由：冲主榜前变动消息非落定点","不中断项指针2条（蒿矢课格+文星不入传），保留")),0.55,NT)
P["LR3-104"]=("方向：上疏得达、蒙纳无罪，正向（单一终局）。断语：占上疏得从革课，三传酉（勾陈）→丑（太常）→巳（贵人），初传勾陈主奏章先被勾留迟滞，中传太常主朝廷常度受理，末传巳火贵人临门、日干癸水得巳中丙戊之官财，主疏终达御前、言得采纳或至少无罪获褒，上疏者本人无谴。应期：跨度定为日档（章奏批答以日计）；窗口为占后一旬内，主坐标取巳日——末传贵人值日、批答落点，依据为逢值路；备选酉日（勾陈留中）只入复推。", LR("辛未年六月癸卯日乙卯时，从革绝嗣课；日干癸为上疏者，朱雀文书虽不入传而末传贵人收束。","勾陈→太常→贵人链由滞转达，贵人收尾定终局。空亡辰巳、申酉落空，初传酉落空主留中更显、末传巳不落空可落点。",rev("初推逢值路：巳日末传值日","复推逢合路：巳酉丑金局、酉位落空不取","两路裁决取巳日，酉点舍弃理由：落空之合不成立","得达断项指针2条（贵人末传+太常中传），保留")),0.52,NT)
P["LR3-107"]=("方向：来客为阴私涉讼之人、来意不善，负向。断语：寓中偶占来客，三传子（天后）→亥（太阴）→戌（玄武）退茹递退，天将自天后、太阴至玄武连乘阴将，无一阳明之将入传，主此人身份卑微隐晦、涉阴私或讼系之事，非贵客非善类；其吉凶主退败潜藏，恐为在逃、行窃或怀叵测之心的夜行之人，宜防不宜亲。应期：跨度定为日档（当面占人以日计）；窗口为当日之内，主坐标取戌时/戌位——末传玄武值位、其人底细见形，依据为逢值路；备选子（初传）只入复推。输入注记：课式首字残泐存疑（卡内自述），降置信。", LR("壬午年七月甲午日庚午时，退茹课（课体首字疑残泐）；日干甲为占者，以三传天将链射来客身份，守指南射覆/偶占之法。","三阴将连传+退茹课格双证阴退之象。空亡辰巳、卯辰落空，不碍戌位。",rev("初推逢值路：戌位末传值位","复推逢冲路：辰位冲戌同日档","两路同档取戌位，辰点舍弃理由：冲主占者警觉非其人见形点","身份断项指针1条（三阴将链为一组结构指针），按R61-REV1-4降为类别倾向（阴私涉讼一类）交付")),0.44,NT)
P["LR3-110"]=("方向：马可找回，正向（单一终局）。断语：占失马，知一课主专向一处寻，三传卯（朱雀）→戌（白虎）→巳（贵人），初传卯木在东方、朱雀主有鸣声消息，主马向东方走失、先于卯方得信；中传戌乘白虎主马在西北方人家厩舍或关拦之处，末传贵人主终得贵人指引领回。应期：跨度定为日档（寻失物以日计）；窗口为占后一旬内，主坐标取巳日——末传值日、马得回，依据为逢值路（六壬失物逢值/逢冲合三路取一）；备选卯日（得信）只入复推。方位为断项粒度：初传单指针指东方，按复核降为方位交付，不断具体处所。", LR("庚寅年十月癸卯日庚申时，知一斫轮课；日干癸为失主，马类神以午火与初传并参（午不入传，故专取初传方位）。","朱雀初传主消息先至，白虎中传主关拦，贵人收尾主得回。空亡辰巳、亥子落空，末传巳落空一节主得回之期稍虚，故窗口放宽至一旬。",rev("初推逢值路：巳日末传值日","复推逢冲路：亥日冲巳、落空之冲同窗后点","两路异点，按末传落空裁决：巳日为主坐标而置信降档，亥日舍弃理由：亥落空、冲空主虚信","方位断项指针1条（初传卯木），按R61-REV1-4降为方位（东方）交付；处所断项指针1条（白虎戌位）降为区域（西北方人家厩舍一带）交付")),0.50,NT)
P["LR3-112"]=("方向：病可愈，正向（单一终局）。断语：自占病得元首润下课，三传辰（玄武）→申（青龙）→子（螣蛇），申子辰水势润下主痰湿水气之病，初传玄武主病因暗昧，中传申金青龙为医药喜神入传生身，末传子水螣蛇只主愈后尚有缠扰余波；主病不入墓绝、药石得力，终局向愈而愈期稍迟。应期：跨度定为月档（湿滞之病以月计）；窗口为占后一月内，主坐标取子位——末传值位、水势退尽见愈，依据为逢值路；备选申（青龙药神）只入复推。对象复述：承受对象=刘一纯本人，应验对象=三传所主病者本人，同一。", LR("辛未年正月戊申日己未时，元首润下课；日干戊土，辰为水库乘玄武主湿病之因。","青龙居中传为疾病门救应，润下课格主病势下行而解。空亡寅卯、午未落空，不碍申子辰链。",rev("初推逢值路：子位末传值位","复推逢合路：申子辰合局、申位同档前点","两路同档取子位收束，申点舍弃理由：申主药力至、非愈点","向愈断项指针2条（青龙入传+病不入墓），保留")),0.50,NT)
P["LR3-114"]=("方向：鸦鸣主口舌丧信之扰、轻凶，负向（单一终局，轻级）。断语：半夜闻鸦鸣占应候，重审退茹课，三传子（太常）→亥（玄武）→戌（太阴），玄武居中主暗昧失信，太阴收尾主阴人私事，主此鸣应在一场近邻或亲属间的丧信、口舌或失物之扰，不应占者本人大凶，只到音信惊扰层级。应期：跨度定为日档（应候以日计）；窗口为占后一旬内，主坐标取戌日——末传值日、音信落定，依据为逢值路；备选亥日（玄武值日）只入复推。", LR("己丑年三月乙丑日丁亥时，重审退茹课；占时亥时正合鸦鸣之时，以发动之传为应。","退茹主事退而信至，玄武太阴链主阴私音信。空亡戌亥、酉戌落空，中末传俱涉空，主音信虚实参半故降级。",rev("初推逢值路：戌日末传值日","复推出空路：亥玄武逢亥出空同窗","两路异点取戌日，亥日舍弃理由：出空主始闻惊扰非落定点","丧信断项指针1条（玄武太阴链），按R61-REV1-4降为倾向表述（丧信/口舌/失物三者居其一象）交付")),0.44,NT)
P["LR3-116"]=("方向：射覆断物——袖中为圆而柔之物（果类/卵类一类）。断语：八专课三传丑（贵人）→亥（太阴）→亥（太阴），亥水太阴双见主阴柔、圆润、藏于暗处之物，丑土贵人主其物为日常贵重小物而非利器；合断袖帨所包为一枚圆形柔软之物，以果品（橘、橙一类）或卵类最合象，质地柔、水分多，非金属非尖利之器。应期：射覆无应期之问，明写无应期、R61-REV1-2/-3不适用（以开封当场为验）。置信分层：圆柔类别层中、具体品种层低，只断类别不断确品。", LR("辛巳年八月甲寅日壬申时，八专课；日干甲木，物类以三传五行与天将取象：亥水主圆润流体、太阴主阴藏柔物、丑土主包裹。","卡内注记：三传后两传天干未载、旬空未载，输入残损，降置信；只据地支与天将作类别断。断项粒度核：类别断项指针2条（亥水双见+太阴双乘）指向圆柔类同一落点，保留类别粒度；具体品种指针0条，删确品、只留果/卵类别带。", "R61-REV1-2：无应期断语，明写不适用。"),0.36,NT)
# LY liuyao
P["LY-001"]=("方向：将来有官，正向（单一终局）。断语：两卦合断：初占兑为泽，官鬼巳火初爻动而父母未土五爻动，野鹤疑之命再占，得水地比静卦，官鬼卯木持世（比卦世爻官鬼卯木）、亥月生扶，官星持世得月生，主将来必有官职入手；然初卦官动逢月令休囚、父动主先有文书波折，主得官迟、须历一番周折与等待，非少年速发之官。应期：跨度定为年档（仕途得官以年计，先定年不径落日）；窗口为占后数年内，主坐标取卯年——再占官星值年，依据为逢值路；备选巳年（初卦官爻值年）只入复推。", B("liuyao","六爻纳甲单法（两卦合断，从再占为主、初占为辅）","初占兑化讼，再占水地比静卦。对象核对：承受对象=求测者本人，应验对象=官鬼爻所主之官职归于世爻本人，同一。动化定性核对：动化方向—初卦巳火动、未土动无化进定性；反转条件—再占官持世得生，不构成凶翻转。"+rev("初推逢值路：卯年官星值年","复推逢值异路：巳年初卦官爻值年同为年档后点","两路异点，按合断权重取再占官星卯年，巳年舍弃理由：初占为疑卦、权重次之","得官断项指针2条（官持世+月生扶），保留；迟得断项指针1条降为倾向表述")),0.55,LYT(False,True,True,"两卦合断：初占后命再占，两卦权重取舍本身即争议点，故disputed=true；终局取再占为主并在reason注明，初占官爻动向作为reserve参考路保留于复推（reserve_used=true，指复推中保留初占一路候选，非改主断）。"))
P["LY-002"]=("方向：父归，正向（单一终局）。断语：占父何日归，以父母为用神，父母戌土上爻持世独发，动而化未土退位，父已在归途、动爻即归信；辰月戊子日，戌土得月辰冲、日辰子水不克土，用神旺动，主父必归。应期：跨度定为日档（候归以日计、独发之爻支持日级定位）；窗口为占后一旬内，主坐标取戌日——用神动爻值日，依据为逢值兼动逢值则应；备选辰日（月建冲动用神）只入复推。", B("liuyao","六爻纳甲单法","乾为天之泽天夬，上爻父母戌土独发。对象复述（行人类）：承受对象=求测者之父，应验对象=父母戌土所指之父，同一，逐名对回无泛称。动化定性核对：动化方向—戌化未为化退，主归途渐近家门之退位归宅，不作退败解（行人门化退主归）；反转条件—无不归信号全立。"+rev("初推逢值路：戌日用神值日","复推冲实路：辰日月建冲动同窗前点","两路异点取戌日（动爻逢值则应为行人门首选），辰日舍弃理由：冲动主已动身之应、非抵家点","归家断项指针2条（用神持世独发+旺动），保留")),0.60,LYT(False,False,False,"用神独发旺动，初判归即定，无改判；化退按行人门作归宅解、非争议。"))
P["LY-003"]=("方向：子病凶，负向（单一终局）。断语：占子病以子孙为用，子孙午火伏于世爻妻财丑土之下，酉月金旺火囚，伏神午火休囚无气，飞神丑土泄火之气，卦中官鬼酉金两现旺相克伐无制（子孙伏藏不能制鬼），主子病沉重、药力难施，凶多吉少。应期：跨度定为日档（近病危重以日计）；窗口为占后一旬内，主坐标取午日——伏神值日出头而正逢囚地、危象见形，依据为逢值；备选酉日（鬼旺值日）只入复推。", B("liuyao","六爻纳甲单法","地风升静卦，子孙午火伏世下。对象复述（病占）：承受对象=患病之子，应验对象=伏神子孙午火所指之子，同一。动化定性核对：动化方向—静卦无动化；反转条件—伏神无原神发动来生，不达翻转门槛。病占原神即子孙本身伏藏，源弱成文。"+rev("初推逢值路：午日伏神值日","复推逢冲路：子日冲午同窗","两路异点取午日（伏神露头受囚），子日舍弃理由：冲伏主惊动消息非危候主点","凶象断项指针2条（用神伏囚+鬼旺无制），保留")),0.60,LYT(False,False,False,"静卦用神伏囚，初判凶即定，无改判无歧义。"))
P["LY-004"]=("方向：父病大凶、不治，负向（单一终局）。断语：四度占父病（卡内setting自述病势甚危）：首卦地雷复父母巳火伏官鬼寅木之下受生而泄、再占山泽损父母巳火初爻临位，后两卦风山渐之巽父母午火动化妻财亥水回头克——四卦同指一事：用神或伏或动化回头克，无一卦得子孙原神制鬼救应，主父病入险、不治之局已成。应期：跨度定为日档（危病以日计）；窗口为占后一旬内，主坐标取午日——后卦动爻父母午火值日、化水克身之应最显，依据为逢值；备选巳日（前卦用神值日）只入复推。", B("liuyao","六爻纳甲单法（多卦合断，四卦同权同向）","复、损静卦，渐之巽五爻父母午火动化亥水回头克。对象复述（病占）：承受对象=患病之父（本人、次子、长子、夫人四占同指一人），应验对象=父母爻所指之父，逐名对回同一。动化定性核对：动化方向—午化亥回头克为定性主据；反转条件—四卦无一救应，不翻转。"+rev("初推逢值路：午日动爻值日","复推冲实路：巳日前卦用神值日同窗前点","两路异点取午日（回头克之应点权重最高），巳日舍弃理由：伏神值日主病象露头非终局点","不治断项指针3条（伏、临位无救、动化回头克），保留")),0.65,LYT(False,False,False,"四卦同向同指，无改判；多卦为同题复占合断、非读法争议，disputed=false。"))
P["LY-005"]=("方向：乡试中试，正向（单一终局）。断语：占乡试以官鬼为功名、父母为文书；五爻官鬼申金动化酉金化进神，申月当令官星旺相化进，世爻官鬼酉金同气临身，父母亥水得申金动生，主功名进益、文书顺遂，此试可中，名次不至榜尾。应期：跨度定为月档（试事以榜期月计，先定月）；窗口为放榜之月，主坐标取申酉之月内酉日层级——官星化进值位，依据为化进逢值（月档内以酉为坐标）；备选亥（父母值位）只入复推。", B("liuyao","六爻纳甲单法","雷风恒之泽风大过，五爻官鬼申金动化酉金进神。对象核对：承受对象=应试者本人，应验对象=官鬼所主功名归于世爻本人，同一。动化定性核对：动化方向—申化酉化进神为定性主据，主进；反转条件—无退神/回头克，不翻转。"+rev("初推化进逢值路：酉位进神值位","复推逢生路：亥水父母得生值位同档","两路同档取酉位（功名主点），亥点舍弃理由：父母主文书过程非功名落点","中试断项指针2条（官化进神+官持世），保留")),0.65,LYT(False,False,False,"官星化进，初判中试即定，无改判无歧义。"))
P["LY-006"]=("方向：求婚不成，负向（单一终局）。断语：占求婚以世为己、应为对方、妻财为女方；四爻俱动、卦逢多动主乱：世爻妻财未土动化戌土，官鬼酉金动化申金退神，子孙巳火动化子水回头克，父母子水初爻动化未土——财官俱动而官退、世应之间兄弟寅木居应克世，主多方阻挠、媒议反复，终局婚事不成。应期：跨度定为月档（婚议以月计）；窗口为议婚后两月内，主坐标取酉位之月——官爻值位而退、事败落定，依据为逢值兼化退；备选未（世财值位）只入复推。卦名原文未直书、据装卦推得（卡内自述），标注留痕。", B("liuyao","六爻纳甲单法；输入注记：卦名据装卦推得非原文直书（卡内自述）","山火贲之水地比，初、四、五、上四爻动。对象核对：承受对象=求婚者本人与所求之女方，应验对象=世应与妻财爻所指双方，同一。动化定性核对：动化方向—官化退神、子孙化回头克，多动定性主乱而败；反转条件—财持世动本为成婚之路，然官退应克，不达翻转门槛，只降置信。"+rev("初推逢值路：酉位官爻值位","复推化退路：申位退神值位同档相邻","两路同尺度相距一单位步进，按原序取酉位、不对决，申位舍弃理由：退神过程点","不成断项指针2条（官化退+应克世），保留")),0.55,LYT(False,False,True,"卦名非原文直书、系据装卦推得（卡内自述），装卦本身无歧但来源一节存疑，故disputed=true留痕；断语按装卦表作断。"))
P["LY-007"]=("方向：迎之不遇、父自归家，负向于相遇（单一终局）。断语：占迎父能否相遇，以父母为父、世为迎者；父母戌土五爻动化未土，父行已动而化退主渐近家门；世爻兄弟申金动化酉金，迎者空往一程，上爻子孙子水动化巳火——三动交错主两路错身：迎者外出之时父已由他途抵家，主途中不遇、迎空而返而父安归。应期：跨度定为日档（迎人以日计）；窗口为占后数日内，主坐标取戌日——父母动爻值日、父抵家之日，依据为逢值；备选申日（世爻动、迎者出行）只入复推。卦名据装卦推得（卡内自述），标注留痕。", B("liuyao","六爻纳甲单法；输入注记：卦名据装卦推得非原文直书（卡内自述）","水泽节之火泽睽，上、五、四三爻动。对象复述（行人类）：承受对象=归家之父与外出迎者，应验对象=父母戌土所指之父、世爻所指迎者，逐名对回同一。动化定性核对：动化方向—父化退主归宅、世化进主迎者远出，两路反向正成错身之象；反转条件—无相遇之合（世父无合），不翻转。"+rev("初推逢值路：戌日父爻值日","复推冲实路：辰日冲戌同窗前点","两路异点取戌日（抵家落点），辰日舍弃理由：冲动主父已动身之应","不遇断项指针2条（三动错身+世父无合），保留")),0.55,LYT(False,False,True,"卦名非原文直书、系据装卦推得（卡内自述），来源一节存疑，故disputed=true留痕；断语按装卦表作断。"))
P["LY-008"]=("方向：病势退减难全愈、凶多，负向（单一终局）。断语：占危症以世为病人，世爻子孙酉金（福神兼药神）独发本主药力得施，然酉化申为化退神——进神退神章之例：子孙化退主药效渐退、病势先有一线转机而后复退，官鬼寅木临应得卯日生扶暗伏，主终局病危难全愈，防退象见形后转重。应期：跨度定为日档（危病以日计）；窗口为占后一旬内，主坐标取申日——退神值日、退象落定，依据为化退逢值；备选酉日（世爻值日、初见转机）只入复推。", B("liuyao","六爻纳甲单法","泽天夬之雷天大壮，五爻子孙酉金世动化申金退神（原书进神退神章例）。对象复述（病占）：承受对象=抱危症之病人本人，应验对象=世爻子孙所指之本人，同一。动化定性核对：动化方向—酉化申化退神为定性主据，主退；反转条件—子孙动本为愈路，化退不达翻转愈局门槛，只留近段转机之述。"+rev("初推化退逢值路：申日退神值日","复推逢值异路：酉日世爻值日同窗前点主初转机","两路异点，按终局段（退象）取申日，酉日舍弃理由：酉主近段转机过程点、非终局点","难愈断项指针2条（世化退神+鬼临应得日生），保留")),0.55,LYT(False,False,False,"退神定性明确，初判即定终局，无改判无歧义。"))

assert set(P.keys())==set(IDS), (set(IDS)-set(P.keys()), set(P.keys())-set(IDS))
outdir = ROOT/"predictions"; outdir.mkdir(exist_ok=True)
for cid in IDS:
    txt, basis, conf, trig = P[cid]
    rec = {"case_id":cid,"prediction_text":txt,"basis":basis,"confidence":conf,"trigger":trig}
    (outdir/f"{cid}.json").write_text(json.dumps(rec,ensure_ascii=False,indent=2),encoding="utf-8")
print("written", len(P))
